using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Geometry;

internal sealed class FiniteFaceLinkCollapseDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Finite face-link collapses through exact frames and original graph residual consumers.",
        H("Finite collapse geometry"),
        Blocks(
            Paragraph(Text("The face link, antistar, and current frame all use the same finite original vertex type. A sequence replayed through exact current frames records ordered pairs and every intermediate frame, fixes the whole antistar, and feeds the literal graph residual complex; empty erased faces occur only through AugmentedFace and no ghost vertex is materialized.")),
            Node("mem-face-link", "mem_faceLink", "Exact nonempty face-link membership",
                "For any K, E and s, s belongs to faceLink K E exactly when s is nonempty, DisjointFrom E s and E union s belongs to K. These are the actual source hypotheses on original labels.", DescribeRole.Theorem),
            Node("mem-face-antistar", "mem_faceAntistar", "Exact antistar membership",
                "For any K, E and s, s belongs to faceAntistar K E exactly when s belongs to K and E is not a subset of s. The equation concerns full faces, with no extra independence or nonemptiness premise on E.", DescribeRole.Theorem),
            Node("mem-face-frame", "mem_faceFrame", "Exact current-frame membership",
                "For any K, E, M and s, s belongs to faceFrame K E M exactly when s belongs to K and either E is not a subset of s or s minus E is an AugmentedFace of M. The augmented empty face is retained.", DescribeRole.Theorem),
            Node("disjoint-from", "DisjointFrom", "Original-label disjointness",
                "DisjointFrom E s means every x∈E is absent from s; E and s stay finite subsets of the same original V.", DescribeRole.Definition),
            Node("face-link", "faceLink", "Nonempty face link",
                "faceLink K E has faces s satisfying s.Nonempty, DisjointFrom E s, and E∪s∈K. The empty face is excluded from the realization carrier.", DescribeRole.Definition),
            Node("face-antistar", "faceAntistar", "Whole antistar",
                "faceAntistar K E has exactly s∈K with E not⊆s. It includes every original component and every face avoiding E.", DescribeRole.Definition),
            Node("face-frame", "faceFrame", "Current frame from an augmented link",
                "faceFrame K E M has s∈K and either E is not⊆s or AugmentedFace M (s minus E). The augmented empty branch controls an empty erased face combinatorially only.", DescribeRole.Definition),
            Node("antistar-frame", "faceAntistar_le_frame", "Antistar lies in every frame",
                "faceAntistar K E ≤ faceFrame K E M.", DescribeRole.Theorem),
            Node("frame-le", "faceFrame_le", "Frame is an original subcomplex",
                "faceFrame K E M ≤ K.", DescribeRole.Theorem),
            Node("frame-link-eq", "faceFrame_link_eq", "Initial frame identity",
                "For hE : E.Nonempty, faceFrame K E (faceLink K E) = K, including the empty erased face only through AugmentedFace.", DescribeRole.Theorem),
            Node("frame-containing", "faceFrame_containing_iff", "Containing-face frame criterion",
                "If M≤faceLink K E and hs:s∈K, then E⊆s implies s∈faceFrame K E M iff AugmentedFace M (s minus E).", DescribeRole.Theorem),
            Node("frame-link", "faceFrame_link", "Exact intermediate link",
                "If M≤faceLink K E, faceLink (faceFrame K E M) E = M on the original label type.", DescribeRole.Theorem),
            Node("frame-coface", "faceFrame_coface_iff", "Coface correspondence",
                "For M≤faceLink K E, P.ambient=M, hs:s∈faceFrame K E M, and hEs:E⊆s, E∪P.lower ⊂ s iff P.lower ⊂ s minus E. The containing-E hypothesis is necessary because every antistar face is retained. This is the exact bridge used by every lifted free pair.", DescribeRole.Theorem),
            Node("lifted-pair-spec", "lifted_pair_spec", "Lifted freeness specification",
                "For hM:M≤faceLink K E, P.ambient=M, hPsub:M≤faceFrame K E M, every s∈faceFrame K E M with E∪P.lower⊂s equals E∪P.upper.", DescribeRole.Theorem),
            Node("link-singleton", "faceLink_singleton", "Singleton link identity",
                "faceLink K {v} = link K v, with the same nonempty original-label faces and v-avoidance.", DescribeRole.Theorem),
            Node("link-insert", "faceLink_insert", "Insertion link identity",
                "If v∉F, faceLink K (insert v F) = faceLink (link K v) F, preserving the original coordinate carrier.", DescribeRole.Theorem),
            Node("antistar-singleton", "faceAntistar_singleton", "Singleton antistar identity",
                "faceAntistar K {v} = deletion K v.", DescribeRole.Theorem),
            Node("frame-insert", "faceFrame_insert", "Insertion frame decomposition",
                "For F.Nonempty, v∉F, {v}∈K, and M≤faceLink K (insert v F), faceFrame K (insert v F) M = deletion K v ⊔ cone v (faceFrame (link K v) F M). The v∈s branch retains the augmented apex singleton.", DescribeRole.Theorem),
            Node("antistar-insert", "faceAntistar_insert", "Insertion antistar decomposition",
                "For F.Nonempty, v∉F, and {v}∈K, faceAntistar K (insert v F) = deletion K v ⊔ cone v (faceAntistar (link K v) F). The singleton erased-face branch is present only because F is nonempty.", DescribeRole.Theorem),
            Node("frame-singleton", "faceFrame_singleton", "Singleton frame decomposition",
                "For M≤link K v and {v}∈K, faceFrame K {v} M = deletion K v ⊔ cone v M.", DescribeRole.Theorem),
            Node("pair-lifted-by", "PairLiftedBy", "Original pair transport relation",
                "PairLiftedBy D v P Q means that P is exactly Pair.liftPairOver Q D v with explicit ambient and Fresh witnesses; the output pair is first and source pair second.", DescribeRole.Definition),
            Node("pairs-lifted", "pairs_liftOver_forall2", "Lifted ordered-pair relation",
                "For S:Sequence M N, List.Forall₂ (PairLiftedBy D v) relates (S.liftOver D v hMD hvD).pairs to S.pairs in order.", DescribeRole.Theorem),
            Node("pair-union-spec", "PairUnionSpec", "Inserted-face pair specification",
                "PairUnionSpec E d P Q asserts P.lower=E∪Q.lower, P.apex=Q.apex, and P.upper=E∪Q.upper.", DescribeRole.Definition),
            Node("singleton-collapse", "singletonFaceCollapse", "Singleton face-link collapse",
                "singletonFaceCollapse K v d consumes a Sequence on faceLink K {v} and returns the lifted sequence over faceAntistar K {v}; it reuses the original singleton linkCollapseDeletion owner and remains available independently of the general frame replay.", DescribeRole.Definition),
            Node("face-link-collapse", "faceLinkCollapse", "General face-link collapse",
                "faceLinkCollapse K E d hE hEK S replays S with each current ambient equal to faceFrame K E M, adjoining E to both faces of every original pair, and appends the exact final pair with lower E, apex d, and upper E∪{d}. It handles every nonempty E, including singletons, in the original Sequence owner. The output carrier is the exact faceAntistar K E on original labels.", DescribeRole.Definition),
            Node("terminal-data", "terminal_data", "Derived terminal label and coface",
                "For S:Sequence (faceLink K E) (vertexComplex d), the source sequence itself proves d∉E and E∪{d}∈K. No ghost-vertex or edge premise is added.", DescribeRole.Theorem),
            Node("collapse-pair-count", "faceLinkCollapse_pair_count", "Exact pair count",
                "For hE:E.Nonempty, hEK:E∈K, and S, (faceLinkCollapse K E d hE hEK S).pairs.length = S.pairs.length + 1. The extra terminal pair is counted exactly.", DescribeRole.Theorem),
            Node("collapse-ordered-pairs", "faceLinkCollapse_ordered_pairs", "Ordered pair and terminal specification",
                "There exist qs q with output pairs = qs ++ [q], List.Forall₂ (PairUnionSpec E d) qs S.pairs, q.lower=E, q.apex=d, and q.upper=E∪{d}. The theorem preserves output/source order and does not replace it by an untracked witness.", DescribeRole.Theorem),
            Node("collapse-frames", "faceLinkCollapse_frames", "Exact n+1 frame specification",
                "For every i < S.pairs.length+1, the output frame getD i K equals faceFrame K E (S.frames.getD i (faceLink K E)). This quantifies over every intermediate frame, including the terminal frame index.", DescribeRole.Theorem),
            Node("face-link-result", "FaceLinkLiftResult", "Packaged face-link lift result",
                "FaceLinkLiftResult stores the actual output Sequence K (faceAntistar K E), derived d-not-in-E and terminal coface, exact pair count, ordered-pair relation, n+1 frame specification, exact link of every source frame, and a homotopy fixed on the whole antistar realization.", DescribeRole.Definition),
            Node("face-link-lift", "faceLinkLift", "Constructed packaged result",
                "faceLinkLift builds FaceLinkLiftResult from faceLinkCollapse, terminal_data, pair/frame theorems, faceFrame_link, and Sequence.collapseHomotopy_fixed.", DescribeRole.Definition),
            Node("fixed-antistar", "fixed_faceAntistar", "Whole antistar fixed",
                "For R:FaceLinkLiftResult, every t:I and x:Space K with x.val∈realization(faceAntistar K E) satisfies R.sequence.collapseHomotopy (t,x)=x. The fixed set is the complete realized antistar.", DescribeRole.Theorem),
            Node("deletion-antistar", "deletion_le_faceAntistar", "Each original deletion lies in the antistar",
                "If e∈E, deletion K e ≤ faceAntistar K E as a face-collection inclusion.", DescribeRole.Theorem),
            Node("fixed-whole-deletion", "fixed_whole_deletion", "Whole deletion fixed through actual inclusion",
                "For e∈E and x:Space(deletion K e), the same collapse homotopy fixes realizationInclusion (deletion_le K e) x in Space K; deletion_le_faceAntistar he proves that its unchanged coordinates lie in the fixed antistar. This retains disconnected components and all original coordinates.", DescribeRole.Theorem),
            Node("residual-predicate", "residualPredicate", "Graph residual predicate",
                "For a simple graph G and finite face E, residualPredicate G E x means x∉E and x is nonadjacent to every original e∈E.", DescribeRole.Definition),
            Node("graph-face-link", "graph_faceLink_eq_restricted", "Graph face link as restricted complex",
                "If E is nonempty and G.IsIndepSet (E:Set V), faceLink of the actual independence complex equals restricted G (residualPredicate G E). The equality is on nonempty original-label finite faces.", DescribeRole.Theorem),
            Node("edge-residual", "edgeResidualPredicate", "Literal edge residual predicate",
                "edgeResidualPredicate G b c x is x≠b, x≠c, ¬G.Adj b x, and ¬G.Adj c x. It keeps the graph consumer on original labels.", DescribeRole.Definition),
            Node("edge-residual-eq", "edge_residualPredicate_eq", "Pair residual equality",
                "For b≠c, residualPredicate G {b,c} = edgeResidualPredicate G b c as predicates on V.", DescribeRole.Theorem),
            Node("edge-antistar", "edge_antistar_union_deletions", "Edge antistar union of whole deletions",
                "For any K and b,c, faceAntistar K {b,c} = deletion K b ⊔ deletion K c as an equality of face collections, not merely vertex sets.", DescribeRole.Theorem),
            Node("graph-edge-lift", "graph_edge_faceLinkLift", "Graph edge consumer",
                "Given b≠c, an independent edge, an actual sequence S on restricted G (edgeResidualPredicate G b c), the edge face in the independence complex, and the exact face-link equality hres, graph_edge_faceLinkLift returns FaceLinkLiftResult for the cast sequence. The only transport is equality cast; no mapHomeomorph invents a combinatorial sequence.", DescribeRole.Definition)
            )));

    private const string Prefix = "D5/S3/Geometry/FiniteFaceLinkCollapse.";

    private static DocumentBlock Node(string id, string declaration, string heading, string prose,
        DescribeRole role) => Describe.Lean(
        DescribeId.Create(id),
        DeclarationHandle.Create(Prefix + declaration), H(heading),
        StatementSource.FromLean(), AssessedProvenance.FromRepo(),
        Blocks(Paragraph(Text(prose))), role);
}
